<?php
require_once __DIR__.'/include/config.php';hms_start_session();$role=(string)($_SESSION['role']??'');if(!in_array($role,['doctor','admin'],true)){http_response_code(403);exit('Sign in required.');}hms_require_role($role);$actor=(int)$_SESSION['id'];$doctorId=$role==='doctor'?$actor:(filter_input(INPUT_POST,'doctor_id',FILTER_VALIDATE_INT)?:filter_input(INPUT_GET,'doctor_id',FILTER_VALIDATE_INT)?:0);$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){hms_verify_csrf();$action=hms_post_string('action',30);$doctorId=$role==='doctor'?$actor:(int)($_POST['doctor_id']??0);$d=hms_db_query($con,'SELECT id FROM doctors WHERE id=?',[$doctorId]);if(!$d||!$d->num_rows)$message='Select a valid doctor.';elseif($action==='add_rule'){$weekday=filter_var($_POST['weekday']??null,FILTER_VALIDATE_INT);$start=hms_post_string('start_time',5);$end=hms_post_string('end_time',5);$minutes=filter_var($_POST['slot_minutes']??null,FILTER_VALIDATE_INT);$capacity=filter_var($_POST['capacity']??null,FILTER_VALIDATE_INT);$validTime=static fn($v)=>preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',$v);if(!$weekday||$weekday<1||$weekday>7||!$validTime($start)||!$validTime($end)||$end<=$start||!$minutes||$minutes<5||$minutes>240||!$capacity||$capacity>25)$message='Enter a valid weekday, working window, slot length and capacity.';else{$overlap=hms_db_query($con,'SELECT id FROM doctor_availability WHERE doctorId=? AND weekday=? AND isActive=1 AND startTime < ? AND endTime > ? LIMIT 1',[$doctorId,$weekday,$end,$start]);if($overlap&&$overlap->num_rows)$message='This working window overlaps an existing active rule.';else{hms_db_query($con,'INSERT INTO doctor_availability (doctorId,weekday,startTime,endTime,slotMinutes,maxPerSlot,isActive) VALUES (?,?,?,?,?,?,1)',[$doctorId,$weekday,$start,$end,$minutes,$capacity]);$message='Availability rule saved.';}}}elseif($action==='block_date'){$date=hms_post_string('unavailable_date',10);$parsed=DateTimeImmutable::createFromFormat('!Y-m-d',$date);if(!$parsed||$parsed->format('Y-m-d')!==$date||$date<date('Y-m-d'))$message='Choose today or a future unavailable date.';else{hms_db_query($con,'INSERT INTO doctor_unavailable_dates (doctorId,unavailableDate,reason) VALUES (?,?,?)',[$doctorId,$date,hms_post_string('reason',255)?:null]);$message='Unavailable date saved.';}}elseif($action==='delete_rule'){hms_db_query($con,'DELETE FROM doctor_availability WHERE id=? AND doctorId=?',[(int)($_POST['rule_id']??0),$doctorId]);$message='Availability rule removed.';}elseif($action==='delete_block'){hms_db_query($con,'DELETE FROM doctor_unavailable_dates WHERE id=? AND doctorId=?',[(int)($_POST['block_id']??0),$doctorId]);$message='Unavailable date removed.';}}
$doctors=hms_db_query($con,'SELECT id,doctorName,specilization FROM doctors ORDER BY doctorName');$rules=$doctorId?hms_db_query($con,'SELECT * FROM doctor_availability WHERE doctorId=? ORDER BY weekday,startTime',[$doctorId]):null;$blocks=$doctorId?hms_db_query($con,'SELECT * FROM doctor_unavailable_dates WHERE doctorId=? AND unavailableDate>=CURDATE() ORDER BY unavailableDate',[$doctorId]):null;$days=[1=>'Monday',2=>'Tuesday',3=>'Wednesday',4=>'Thursday',5=>'Friday',6=>'Saturday',7=>'Sunday'];
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Doctor availability | MedTech</title><link rel="stylesheet" href="vendor/bootstrap/css/bootstrap.min.css"><link rel="stylesheet" href="assets/css/styles.css"><link rel="stylesheet" href="assets/css/themes/theme-1.css" /><link rel="stylesheet" href="assets/css/medtech-app.css"><style>.mt-availability-top{align-items:center;background:#fff;border-bottom:1px solid #dbeafe;display:flex;height:70px;justify-content:space-between;padding:0 28px;position:sticky;top:0;z-index:10}.mt-availability-brand{color:#123a6d;font-size:24px;font-weight:700;text-decoration:none}.mt-availability-brand span{color:#1479d4}.mt-availability-user{color:#52708f;font-weight:600}.mt-availability-sidebar{background:#0d3c78;bottom:0;color:#dbeafe;left:0;padding:24px 14px;position:fixed;top:70px;width:240px}.mt-availability-sidebar strong{display:block;font-size:15px;letter-spacing:.08em;margin:0 12px 18px;text-transform:uppercase}.mt-availability-sidebar a{border-radius:8px;color:#eaf4ff;display:block;margin:3px 0;padding:11px 12px;text-decoration:none}.mt-availability-sidebar a:hover,.mt-availability-sidebar a.active{background:#1b6ec2;color:#fff}.mt-availability-main{margin-left:240px;min-height:calc(100vh - 70px);padding:18px}.av-card{border:1px solid #dbeafe;border-radius:14px;box-shadow:0 10px 28px rgba(15,54,103,.08);max-width:1100px;margin:6px auto 25px;background:#fff;padding:28px}.av-card h1{color:#123a6d;margin-top:10px}.av-card h2{color:#164f8f;font-size:21px;margin-top:30px}.av-card p{color:#58718f}.av-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}.av-grid .form-group{margin:0 0 14px}.av-card .btn-primary{background:#1479d4;border-color:#1479d4}.av-card .btn-default{border-color:#aac9e8;color:#124e8d}@media(max-width:767px){.mt-availability-top{height:58px;padding:0 16px}.mt-availability-brand{font-size:20px}.mt-availability-user{font-size:12px}.mt-availability-sidebar{display:flex;gap:5px;overflow-x:auto;padding:7px 10px;position:static;width:auto}.mt-availability-sidebar strong{display:none}.mt-availability-sidebar a{font-size:12px;margin:0;white-space:nowrap}.mt-availability-main{margin-left:0;padding:10px}.av-card{border-radius:10px;padding:18px}.av-card .form-inline .form-control{display:block;margin:8px 0;width:100%}}</style></head><body><header class="mt-availability-top"><a class="mt-availability-brand" href="<?=($role==='doctor'?'doctor/dashboard.php':'admin/dashboard.php')?>"><span>+</span> MedTech</a><div class="mt-availability-user"><?=hms_h(ucfirst($role))?> portal</div></header><aside class="mt-availability-sidebar"><strong><?=hms_h(ucfirst($role))?> navigation</strong><?php if($role==='doctor'):?><a href="doctor/dashboard.php">Dashboard</a><a href="doctor/appointment-history.php">Appointments</a><a href="medical-records.php">Clinical records</a><a href="doctor/prescriptions.php">Prescriptions</a><a href="doctor/laboratory.php">Laboratory</a><a class="active" href="manage-availability.php">Availability</a><a href="doctor/notifications.php">Notifications</a><?php else:?><a href="admin/dashboard.php">Dashboard</a><a href="admin/appointment-history.php">Appointments</a><a href="admin/manage-doctors.php">Doctors</a><a href="admin/billing.php">Billing</a><a href="admin/laboratory.php">Laboratory</a><a class="active" href="manage-availability.php">Availability</a><a href="admin/notifications.php">Notifications</a><?php endif;?></aside><div id="app" class="mt-availability-main"><div class="app-content"><div class="main-content"><div class="wrap-content container"><div class="av-card"><a href="<?=($role==='doctor'?'doctor/dashboard.php':'admin/dashboard.php')?>">← Dashboard</a><h1>Doctor availability</h1><p>Set recurring working windows and block dates. No default availability is assumed.</p><?php if($message):?><div class="alert alert-info"><?=hms_h($message)?></div><?php endif;?>
<form method="get" class="form-inline"><label>Doctor</label> <select name="doctor_id" class="form-control" <?=($role==='doctor'?'disabled':'')?> onchange="this.form.submit()"><option value="">Select doctor</option><?php while($dr=$doctors->fetch_assoc()):?><option value="<?=hms_h($dr['id'])?>" <?=($doctorId==(int)$dr['id']?'selected':'')?>><?=hms_h($dr['doctorName'].' — '.$dr['specilization'])?></option><?php endwhile;?></select><?php if($role==='doctor'):?><input type="hidden" name="doctor_id" value="<?=$doctorId?>"><?php endif;?></form>
<?php if($doctorId):?><h2>Working hours</h2><form method="post"><?=hms_csrf_field()?><input type="hidden" name="doctor_id" value="<?=$doctorId?>"><input type="hidden" name="action" value="add_rule"><div class="av-grid"><div class="form-group"><label>Working day</label><select class="form-control" name="weekday"><?php foreach($days as $n=>$day):?><option value="<?=$n?>"><?=$day?></option><?php endforeach;?></select></div><div class="form-group"><label>Start</label><input class="form-control" type="time" name="start_time" required></div><div class="form-group"><label>End</label><input class="form-control" type="time" name="end_time" required></div><div class="form-group"><label>Minutes per slot</label><input class="form-control" type="number" name="slot_minutes" min="5" max="240" value="30" required></div><div class="form-group"><label>Appointments per slot</label><input class="form-control" type="number" name="capacity" min="1" max="25" value="1" required></div></div><button class="btn btn-primary">Add availability</button></form>
<div class="table-responsive"><table class="table table-striped"><thead><tr><th>Day</th><th>Working window</th><th>Slot</th><th>Capacity</th><th></th></tr></thead><tbody><?php if($rules)while($r=$rules->fetch_assoc()):?><tr><td><?=hms_h($days[$r['weekday']]??'')?></td><td><?=hms_h(substr($r['startTime'],0,5).'–'.substr($r['endTime'],0,5))?></td><td><?=hms_h($r['slotMinutes'])?> min</td><td><?=hms_h($r['maxPerSlot'])?></td><td><form method="post"><?=hms_csrf_field()?><input type="hidden" name="doctor_id" value="<?=$doctorId?>"><input type="hidden" name="action" value="delete_rule"><input type="hidden" name="rule_id" value="<?=hms_h($r['id'])?>"><button class="btn btn-xs btn-danger">Remove</button></form></td></tr><?php endwhile;?></tbody></table></div>
<h2>Unavailable dates</h2><form method="post" class="form-inline"><?=hms_csrf_field()?><input type="hidden" name="doctor_id" value="<?=$doctorId?>"><input type="hidden" name="action" value="block_date"><input class="form-control" type="date" name="unavailable_date" min="<?=date('Y-m-d')?>" required><input class="form-control" name="reason" maxlength="255" placeholder="Reason (optional)"><button class="btn btn-default">Block date</button></form><ul><?php if($blocks)while($b=$blocks->fetch_assoc()):?><li><?=hms_h($b['unavailableDate'])?> <?=hms_h($b['reason'])?> <form method="post" class="hms-inline-form"><?=hms_csrf_field()?><input type="hidden" name="doctor_id" value="<?=$doctorId?>"><input type="hidden" name="action" value="delete_block"><input type="hidden" name="block_id" value="<?=hms_h($b['id'])?>"><button class="btn btn-link">Remove</button></form></li><?php endwhile;?></ul><?php endif;?></div></div></div></div></body></html>
